\underline{Corollary} 1.6.   \underline{Let}  $\underline{A}$  \underline{be a semi-homogeneous cofibered groupoid over}  $\underline{C}_{\Lambda}$ \underline{and consider a diagram}

\begin{center}
\begin{tikzcd}[column sep=small]
a' \arrow[dr, "\alpha"'] & & a_1 \arrow[dl, "\alpha_1"] \\
 & a &
\end{tikzcd}
\end{center}

\SGAvar{\underline{in}  $\underline{A}$  \underline{where}  $\alpha_1$  \underline{is a small prolongation.} \underline{Assume that}  $a$  \underline{is versal for small} \underline{prolongations of}  $e$  . \underline{Then there exists a map}  $a' \overset{\ \rho\ }{\relbar\joinrel\relbar\joinrel\relbar} a_1$  \underline{such that}  $\alpha = \alpha_1 \rho$ \underline{in}  $\underline{A}$  \underline{if and only if there exists a map}  $f : P(a') \rightarrow P(a_1)$  \underline{such that} $P(\alpha) = P(\alpha_1)\cdot f$  \underline{in}  $\underline{C}_{\Lambda}$  .

}{\underline{in}  $\underline{A}$  \underline{where}  $\alpha_1$  \underline{is a small prolongation.} \underline{Assume that}  $a$  \underline{is versal for small} \underline{prolongations of}  $e$  . \underline{Then there exists a map}  $a' \xrightarrow{\ \rho\ } a_1$  \underline{such that}  $\alpha = \alpha_1 \rho$ \underline{in}  $\underline{A}$  \underline{if and only if there exists a map}  $f : P(a') \rightarrow P(a_1)$  \underline{such that} $P(\alpha) = P(\alpha_1)\cdot f$  \underline{in}  $\underline{C}_{\Lambda}$  .

}{F7I-VI-006}\underline{Proof}:  Assume that  $P(\alpha) = P(\alpha_1)\cdot f$  where  $f : P(a') \rightarrow P(a_1)$  . Replacing  $a'$ by its direct image under  $f$  , we may and shall assume that  $P(\alpha) = P(\alpha_1)$  . Set  $R' = P(a_1)$  ,  $R = P(a)$  . Since  $\underline{A}$  is semi-homogeneous, we get a commutative diagram

\begin{center}
\begin{tikzcd}[row sep=large, column sep=small]
 & a'' \arrow[dl, "\beta"'] \arrow[dr, "\beta_1"] & & & & & R'\underset{R}{\times}R' \arrow[dl] \arrow[dr] & \\
a' \arrow[dr, "\alpha"'] & & a_1 \arrow[dl, "\alpha_1"] & & \text{above} & R' \arrow[dr] & & R' \arrow[dl] \\
 & a & & & & & R &
\end{tikzcd}
\end{center}
















