\SGAvar{\underline{Definition} 1.7.   \underline{For each object}  $R$  \underline{in}  $\underline{C}_{\Lambda}$ \underline{we put}  $\overline{\Omega}_R = M/(m_{\Lambda}R+M^2)$  \underline{where}  $\underline{m}_{\Lambda}$ $M$  \underline{are the maximal ideals of}  $\Lambda$ ,  $R$  \underline{respectively.} \underline{It is a finite-dimensional vector space over}  $k$  , \underline{and}  $R \longmapsto \overline{\Omega}_R$  \underline{defines a functor}  $\overline{\Omega} : \underline{C}_{\Lambda} \rightarrow \underline{\underline{V}}$  \underline{where} $\underline{\underline{V}}$  \underline{is the category of finite-dimensional vector spaces over}  $k$  . \underline{If}  $\underline{A}$  \underline{is a} \underline{cofibered category over}  $\underline{C}_{\Lambda}$  , \underline{then the composite functor}  $\underline{A} \xrightarrow{\ P\ } \underline{C}_{\Lambda} \rightarrow \underline{\underline{V}}$  \underline{is, by} \underline{abuse of notation denoted by}  $\overline{\Omega}$  \underline{again.}

