\mathrm{Biext}^1(P,Q;G) \arrow[r, "\sim"] \arrow[d] & \mathrm{Biext}^1(Q,P;G) \arrow[d] \\
\mathrm{Hom}(\underline{\mathrm{Tor}}_1(P,Q),G) \arrow[r, "\sim"] & \mathrm{Hom}(\underline{\mathrm{Tor}}_1(Q,P),G) & ,
