\begin{equation*}
0 \longrightarrow J^n \otimes_{D'\cap T} \longrightarrow \underline{O}_{D'\cap Y} \longrightarrow \underline{O}_{D'\cap\ n\ s^*} \longrightarrow 0 \quad ,
\end{equation*}
de sorte que 


