(a) \underline{Le sous-schéma} $H$ \underline{de} $X$ \underline{défini par l'annulation de} $s$ \underline{est lisse sur} $S$.

\SGAvar{(b) \underline{Localement sur} $X$, \underline{si les} $s_i$ \underline{sont les coordonnées de} $S$ \underline{dans une base de} $\underline{W}^{\vee}$ \underline{les} $s_i$ \underline{forment une suite} $\underline{O}_X$\underline{-régulier et} $\underline{F}$\underline{-régulière.}

}{(b) \underline{Localement sur} $X$, \underline{si les} $s_i$ \underline{sont les coordonnées de} $s$ \underline{dans une base de} $\underline{W}^{\vee}$ \underline{les} $s_i$ \underline{forment une suite} $\underline{O}_X$\underline{-régulière et} $\underline{F}$\underline{-régulière.}

}{F7II-XI-007}(c) \underline{Quelle que soit la suite d'entiers} $k_i$, \underline{non tous nuls, on a}

\begin{equation*}
R^i f_* \; (\underset{i}{\otimes} \; \wedge^{k_i} \; \underline{W} \otimes \Omega^j_{X/S} \otimes \underline{F}) \;=\; 0 \;\; \underline{\text{pour}} \;\; i+j < d \qquad .
\end{equation*}
\underline{Alors, on a} :

\SGAvar{\begin{equation*}\tag{i}
