\begin{equation*}
 \overline{X} = X \times_D \widetilde{D} \; , \quad X^* = X-X_0 = X \times_D D^* \quad \mbox{et} \quad \overline{X}^* = \overline{X} - X_0 = X \times_D \widetilde{D}^* \; .
