On désigne par

\begin{equation}\tag{1.6.3}
u_f(t_1-t_2) \in H^1(S, R^{2d_1-1}f_*\mathbb{Q}_\ell(d_1))
\end{equation}
son image par

\begin{equation}\tag{1.6.4}
u_f : \mathrm{Prim}^{2d_1}(X/S, \mathbb{Q}_\ell(d_1)) \longrightarrow H^1(S, R^{2d_1-1}f_*\mathbb{Q}_\ell(d_1)) \quad .
\end{equation}
(C'est un analogue $\mu(t_1 - t_2)$ de cet élément que Manin étudie dans [5]).

1.6.5. Soit maintenant $z$ un cycle algébrique sur $X \times_S Y$ de codimension $\geq b$ sur chaque fibre de $X \times_S Y$ $^{(*)}$, qui détermine une classe de cohomologie (SGA 5 IV\hspace{2em}):

\begin{equation}\tag{1.6.6}
\mathrm{cl}(z) \in H^{2b}(X \times_S Y, \mathbb{Q}_\ell(b)) \quad .
\end{equation}
Cette classe définit une application (cf (1.2.3))

\begin{equation}\tag{1.6.7}
\mathrm{cl}(z) : H^{2d_1}(X, \mathbb{Q}_\ell(d_1)) \longrightarrow H^{2b}(Y, \mathbb{Q}_\ell(b)) \quad ,
\end{equation}
et si les cycles $z(t_1)$ et $z(t_2)$ sont définis, on a (grâce à la compatibilité SGA 5 IV\hspace{3em} du cup-produit avec les intersections de cycles):

(*) Si $S$ est lisse sur un schéma $T$ (p. ex. $T=\mathrm{Spec}\ k$, $k$ un corps), il suffirait de supposer $z$ de codimension $\geq b$ sur chaque fibre au-dessus de $T$ .


\SGApage{II}{349}

\begin{equation}\tag{1.6.8}
\mathrm{cl}(z) (\mathrm{cl}(t_1) - \mathrm{cl}(t_2)) = \mathrm{cl}(z(t_1) - z(t_2)) \quad .
\end{equation}
La commutativité de (1.4.2) nous donne

\begin{equation}\tag{1.6.9}
\mathrm{cl}(z) (u_f(t_1-t_2)) = u_g(\mathrm{cl}(z(t_1) - z(t_2)))
\end{equation}
Comme corollaire de 1.5.3 , on a alors:

\underline{Proposition} 1.7. \underline{Soient} $t_1$ \underline{et} $t_2$ \underline{deux sections de} $f : X \longrightarrow S$ , $f$ \underline{étant supposé à fibres connexes}, \underline{et soit} $z$ \underline{un cycle algébrique} \underline{sur} $X \times_S Y$ \underline{de codimension} $b$ , \underline{tel que le cycle algébrique}

\begin{equation}\tag{1.7.1}
z(t_1) - z(t_2)
\end{equation}
\underline{soit défini}. \underline{Alors sa classe de cohomologie est primitive} (XVIII 5.8.1). \underline{Si le cycle algébrique} $z_{\overline{\eta}}$ \underline{sur} $X_{\overline{\eta}} \times Y_{\overline{\eta}}$ \underline{induit l'homomorphisme nul}

\begin{equation}\tag{1.7.2}
z_{\overline{\eta}} : H^{2d_1-1} (X_{\overline{\eta}}, \mathbb{Q}_\ell(d_1)) \stackrel{0}{\longrightarrow} H^{2b-1}(Y_{\overline{\eta}}, \mathbb{Q}_\ell(b))
\end{equation}
\underline{alors}

\begin{equation}\tag{1.7.3}
u_g(z(t_1) - z(t_2)) = 0 \quad \underline{\mbox{dans}} \quad H^1(S, R^{2b-1}g_* \mathbb{Q}_\ell(b)) \quad ,
\end{equation}
(\underline{où} $u_g$ \underline{est l'homomorphisme de} XVIII 5.8.1 \underline{intervenant dans} 1.4).


\SGApage{II}{350}


2.  \underline{Un rappel sur le niveau} (Cf. [2], 9.7, 10.1)

2.0.1. Soit  $X$  propre et lisse sur un corps  $k$  algébriquement clos. On a vu (1.2.3) que, pour tout

\begin{equation}\tag{2.0.2}
T \text{ propre, lisse et connexe sur } k \text{ de dimension } d ,
\end{equation}
et tout

\begin{equation}\tag{2.0.3}
\text{cycle algébrique } z \text{ de codimension } b \text{ sur } T \times X,
\end{equation}
la classe de cohomologie

\begin{equation}\tag{2.0.4}
\mathrm{cl}(z) \in H^{2b}(T \times X , \mathbb{Q}_\ell(b))
\end{equation}
donne lieu aux applications

\begin{equation}\tag{2.0.5}
\mathrm{cl}(z) : H^q(T, Q_\ell(i)) \longrightarrow H^{q+2b-2d} (X, \mathbb{Q}_\ell(i+b-d)) .
\end{equation}
On définit \underline{la filtration par le co-niveau}  $(N^j)$  de  $H^q(X,\mathbb{Q}_\ell(i))$

\begin{equation}\tag{2.0.6}
N^j H^q(X,\mathbb{Q}_\ell(i)) = \sum_{(T,z)} \text{images} \quad \mathrm{cl}(z) : H^{q-2j}(T,\mathbb{Q}_\ell(i-j)) \longrightarrow H^q(X,\mathbb{Q}_\ell(i)),
\end{equation}
la somme étant étendue aux couples

\begin{equation}\tag{2.0.7}
(T, z) \qquad \begin{array}{l} T/k \text{ propre lisse et connexe de dimension } d \\ z \text{ cycle algébrique sur } T \times X \text{ de codimension } j+d. \end{array}
\end{equation}
Il faut remarquer qu'on parle parfois de la filtration  $F^j$  \underline{croissante} ``par le niveau''  , définie par

\begin{equation}\tag{2.0.8}
F^j H^q(X, \mathbb{Q}_\ell(i)) = N^{\left[\frac{q-j}{2}\right]} H^q(X, \mathbb{Q}_\ell(i)) .
\end{equation}

\SGApage{II}{351}

Remplaçant  $(T, z)$  par  $(\mathbb{P}^1 \times T, \{pt\} \times z)$  , on voit que

\begin{equation}\tag{2.0.9}
N^j H^q(X, \mathbb{Q}_\ell(i)) \subset N^{j-1}H^q(X, \mathbb{Q}_\ell(i)) .
\end{equation}
Evidemment on a:

\underline{Proposition} 2.1.   \underline{Soient}  $X$  \underline{propre,} \underline{lisse et géométriquement connexe sur un corps}  $k$ ,  $\bar{k}$  \underline{une clôture algébrique de}  $k$ ,  $X_{\bar{k}} = X \otimes_k \bar{k}$  .  \underline{Alors}  $\mathrm{gal}(\bar{k}/k)$  , \underline{agissant sur}  $H^q(X_{\bar{k}}, \mathbb{Q}_\ell(i))$, \underline{préserve la filtration par le co-niveau.}

Des raisonnements standards (cf [2]) montrent les énoncés suivants,

\underline{Proposition} 2.2.  \underline{La filtration par le niveau est invariante par extension des corps algébriquement clos}  $k'/k$  .

\underline{Proposition} 2.3.   \underline{Soient}  $S$  \underline{un schéma réduit et irréductible, à point générique}  $\eta$  , \underline{et}

\begin{equation*}
\pi : X \longrightarrow S
\end{equation*}
\underline{un morphisme propre et lisse,} \underline{à fibres géométriquement connexes.} \underline{Si,} \underline{pour des entiers}  $j$  \underline{et}  $q$  \underline{donnés,} \underline{on a pour la fibre générique géométrique}  $X_{\bar{\eta}}$

\begin{equation}\tag{2.3.1}
H^q(X_{\bar{\eta}}, \mathbb{Q}_\ell) = N^j H^q(X_{\bar{\eta}}, \mathbb{Q}_\ell) ,
\end{equation}
\underline{alors il existe un ouvert non-vide}  $U \subset S$  \underline{tel que en tout point}  $u \in U$  , \underline{on ait pour la fibre géométrique}  $X_{\bar{u}}$

\begin{equation}\tag{2.3.2}
H^q(X_{\bar{u}}, \mathbb{Q}_\ell) = N^j H^q(X_{\bar{u}}, \mathbb{Q}_\ell)
\end{equation}

\SGApage{II}{352}


3. \underline{Application aux pinceaux de Lefschetz}

3.1. \quad A partir de maintenant, on fixe :

(3.1.0) $k$ , un corps algébriquement clos,

(3.1.1) $X \subset \mathbb{P}^{r}$ , un $k$-schéma projectif, lisse et connexe de dimension paire $n$ , qui vérifie (LV) (XVIII 5.2.2) .

Prenons

(3.1.2) $D = \{H_{t}\}_{t \in \mathbb{P}^{1}}$ un pinceau de Lefschetz d'hypersurfaces de degré $d$ , à fibre générique

(3.1.3) $X_{\eta}$ , $\eta =$ le point générique de $\mathbb{P}^{1}$ .

Posons (cf. XVIII 5.4.4)

(3.1.4) $m : X_{\bar{\eta}} \hookrightarrow X \times_{k} k(\bar{\eta})$ l'inclusion ,

(3.1.5) $E^{n-1}(X_{\bar{\eta}}, \mathbb{Q}_{\ell}(i)) =$ l'orthogonal de $m^{*}H^{n-1}(X,\mathbb{Q}_{\ell}(i))$ dans $H^{n-1}(X_{\bar{\eta}},\mathbb{Q}_{\ell}(i))$ .

Nous avons vu (XVIII 6.7.2) que la \underline{formule de Picard-Lefschetz} entraîne

(3.1.6) Si $n$ est pair, tout sous-groupe d'indice fini dans $\mathrm{gal}(k(\bar{\eta})/k(\eta))$ agit de façon irréductible sur $E^{n-1}(X_{\bar{\eta}},\mathbb{Q}_{\ell}(i))$ .

\underline{Proposition} 3.2. \quad \underline{Soit} $D = \{H_{t}\}$ \underline{un pinceau de Lefschetz}, \underline{et supposons} $n = 2m$ \underline{pair.} \underline{Alors ou bien} 


\SGApage{II}{353}

\begin{equation}\tag{3.2.1}
 H^{n-1}(X_{\bar{\eta}},\mathbb{Q}_{\ell}(i)) \subset m^{*}H^{n-1}(X,\mathbb{Q}_{\ell}(i)) + N^{m-1}H^{n-1}(X_{\bar{\eta}},\mathbb{Q}_{\ell}(i))
\end{equation}
\underline{ou bien:}

(3.2.2) \underline{Pour toute courbe} $C$ \underline{propre et lisse sur} $k(\bar{\eta})$ , \underline{et tout} \underline{cycle algébrique} $z$ \underline{sur} $C \times X_{\bar{\eta}}$ \underline{de codimension} $m$ , \underline{l'homomorphisme induit} (1.2.3)

\begin{equation}\tag{3.2.3}
\mathrm{cl}(z) : H^{1}(C, \mathbb{Q}_{\ell}(1+i-m)) \longrightarrow H^{2m-1}(X_{\bar{\eta}},\mathbb{Q}_{\ell}(i))
\end{equation}
\underline{a son image dans} $m^{*}H^{2m-1}(X,\mathbb{Q}_{\ell}(i))$ .

\underline{Démonstration.} Supposons que l'image d'un tel homomorphisme (3.2.3) n'est pas contenue dans $m^{*}H^{n-1}(X,\mathbb{Q}_{\ell}(i))$ , ou, ce qui revient au même, que son image dans $E^{n-1}(X_{\bar{\eta}},\mathbb{Q}_{\ell}(i)) = H^{n-1}(X_{\bar{\eta}},\mathbb{Q}_{\ell}(i)) / H^{n-1}(X,\mathbb{Q}_{\ell}(i))$ n'est pas nulle. Comme cette image est évidemment stable sous l'action d'un sous-groupe d'indice fini dans $\mathrm{gal}(k(\bar{\eta})/k(\eta))$ , l'irréductibilité (3.1.6) de $E^{n-1}(X_{\bar{\eta}},\mathbb{Q}_{\ell}(i))$ se récrit en disant

\begin{equation*}
H^{n-1}(X_{\bar{\eta}},Q_{\ell}(i)) = m^{*}H^{n-1}(X,Q_{\ell}(i)) + \text{l'image de } (3.2.3)
\end{equation*}
et, par définition,

\begin{equation*}
\text{l'image de } (3.2.3) = \text{l'image par } \mathrm{cl}(z) \text{ de } H^{1}(C,\mathbb{Q}_{\ell}(1+i-m)) \subset N^{m-1}H^{n-1}(X_{\bar{\eta}},\mathbb{Q}_{\ell}(i)) ,
\end{equation*}
de sorte qu'on a bien trouvé

\begin{equation*}
H^{n-1}(X_{\bar{\eta}},\mathbb{Q}_{\ell}(i)) = m^{*}H^{n-1}(X,\mathbb{Q}_{\ell}(i)) + N^{m-1}H^{n-1}(X_{\bar{\eta}},\mathbb{Q}_{\ell}(i))
\end{equation*}

\SGApage{II}{354}


3.3. \underline{La condition (B)}.

3.3.1. On dira que l'inclusion

\begin{equation*}
m : X_{\overline{\eta}} \hookrightarrow X \times_{k} k(\overline{\eta})
\end{equation*}
vérifie la condition (B)  s'il existe

(3.3.2) $V_{\overline{\eta}}$ , un cycle algébrique de codimension $n-1$ sur $X_{\overline{\eta}} \times (X \times_{k} k(\overline{\eta}))$ tel que l'application qu'il définit

\begin{equation}\tag{3.3.3}
V_{\overline{\eta}} : H^{n-1}(X_{\overline{\eta}},\mathbb{Q}_{\ell}(i)) \longrightarrow H^{n-1}(X,\mathbb{Q}_{\ell}(i))
\end{equation}
soit inverse à gauche de

\begin{equation}\tag{3.3.4}
m^* : H^{n-1}(X,\mathbb{Q}_{\ell}(i)) \longrightarrow H^{n-1}(X_{\overline{\eta}},\mathbb{Q}_{\ell}(i)) \quad ,
\end{equation}
i.e. tel que l'on ait

\begin{equation}\tag{3.3.5}
V_{\overline{\eta}} \; m^* = \mathrm{id} .
\end{equation}
(3.4). Cette condition (B) est vérifiée si l'opération $\Lambda$ [4, 1.4.2.1] est algébrique (cf. [4, 2.12 (ii)]). On conjecture que $\Lambda$ est toujours algébrique, donc que la condition (B) est toujours vérifiée, et on sait le vérifier dans de nombreux cas [4]. \underline{Elle est vérifiée trivialement pour} $X$ \underline{une intersection complète de dimension} paire car alors on sait (IX 1.6) que

\begin{equation}\tag{3.4.1}
H^{n-1}(X,\mathbb{Q}_{\ell}(i)) \;=\; 0 .
\end{equation}

\SGApage{II}{355}


4. \underline{Le théorème de GRIFFITHS}

\underline{Théorème} 4.1. \underline{Soit} $X$ \underline{projectif,} \underline{lisse et connexe sur} $k$ , \underline{de dimension paire} $n = 2m \geq 4$. \underline{Soit} $D$ \underline{un pinceau de Lefschetz de sections par des hypersurfaces de degré} $d$ . \underline{On suppose}

(4.1.0) $X$ \underline{vérifie} (L V) (XVIII 5.2.2),

(4.1.1) \underline{le pinceau} $D$ \underline{vérifie l'hypothèse} (A) (XVIII 5.3)

(4.1.2) \underline{le pinceau} $D$ \underline{vérifie} (3.2.2), \underline{i.e.} (3.2) \underline{la cohomologie évanescente} $E^{n-1}(X_{\overline{\eta}},\mathbb{Q}_{\ell})$ \underline{n'est pas  de niveau} $\leq 1$ ,

(4.1.3) \underline{l'inclusion} $m : X_{\overline{\eta}} \hookrightarrow X \times_{k} k(\overline{\eta})$ \underline{vérifie l'hypothèse} (B) (3.3).

\underline{Alors,} \underline{si un cycle algébrique} $z$ \underline{de codimension} $m$ \underline{sur} $X$ \underline{est tel que sa restriction (en tant que cycle algébrique) à} $X_{\overline{\eta}}$ \underline{satisfasse}

(4.1.4) $z_{\overline{\eta}} = z|X_{\overline{\eta}}$ \underline{est algébriquement équivalent à zéro}

\underline{Alors} (4.1.5) $z$ \underline{est} \underline{$\mathbb{Q}_{\ell}$-cohomologue à zéro,} \underline{i.e.} $\mathrm{cl}(z) \in H^{2m}(X,\mathbb{Q}_{\ell}(m))$ \underline{est nul}.


4.2. \underline{Une remarque sur le cas où} $X$ \underline{est une intersection complète}.

Comme on l'a déjà remarqué (cf. XVIII 5.2.5 et (3.4)), les hypothèses (4.1.0) et (4.1.3) sont alors automatiquement vérifiées. Quant à l'hypothèse (4.1.1), on a vu (XVIII 6.3.4, 6.4) qu'elle est vérifiée pour un pinceau d'hypersurfaces de degré $d > 2n$. D'autre part, on va prouver dans le prochain exposé la condition (4.1.2) pour un pinceau ``général'' d'hypersurfaces de degré $d > 2n$ (XXI 5.2). Donc un pinceau ``général'' d'hypersurfaces de degré $d > 2n$ vérifie toutes les hypothèses du théorème 4.1.


\SGApage{II}{356}

4.3. Revenant au cas où $X$ est quelconque, il semble très plausible que, pour un degré $d$ assez grand, toutes les conditions de 4.1 soient vérifiées pour $D$, du moins pour $D$ assez général. On a déjà vu que c'est le cas pour (4.1.1) (XVIII 6.4), et on a signalé qu'on conjecture que (4.1.0) et (4.1.3) sont vérifiées dans tous les cas (et c'est vrai dans tous les cas pour (4.1.0) si $\operatorname{car}(k)=0$). Quant à la condition (4.1.2), elle est vérifiée (grâce à la théorie de Hodge) pour $d$ grand si $\operatorname{car}(k)=0$, et des arguments heuristiques (que le lecteur trouvera en appendice à l'exposé suivant) rendent plausible qu'il en est encore de même si $\operatorname{car}(k)>0$. Plus généralement, ces arguments (théorie de Hodge, resp. cohomologie cristalline) prouvent (resp. rendent plausible) que, pour une variété projective lisse $X$ de dimension $n$, et pour tout pinceau de Lefschetz $D$ d'hypersurfaces de degré $d$ assez grand (resp. tout pinceau $D$ ``assez général'' d'hypersurfaces de degré $d$), la cohomologie évanescente $E^{n-1}(X_{\bar{\eta}}, \mathbb{Q}_{\ell})$ est de niveau égal à $n-1$ (i.e. n'est pas de niveau $\leqslant n-3$, i.e. n'est pas de coniveau 1).


4.4.  \underline{Démonstration du théorème de Griffiths.}

Soit $z$ un cycle algébrique de codimension $m$ sur $X$, tel que

\begin{equation}\tag{4.4.1}
z_{\bar{\eta}} = z|X_{\bar{\eta}} \quad \text{est algébriquement équivalent à zéro} \quad .
\end{equation}
Par définition, il existe

\begin{equation}\tag{4.4.2}
\text{une courbe} \quad C_{\bar{\eta}} \quad \text{, propre, lisse et connexe sur} \quad k(\bar{\eta}) , 
\end{equation}

\SGApage{II}{357}

\begin{equation}\tag{4.4.3}
 \text{deux sections} \; t_{i}(\bar{\eta}) : \mathrm{Sp}(k(\bar{\eta})) \longrightarrow C_{\bar\eta} \quad , \; i=1,2 \quad ,
\end{equation}
\begin{equation}\tag{4.4.4}
\text{un cycle algébrique} \quad P_{\bar{\eta}} \quad \text{sur} \quad C_{\bar{\eta}} \times X_{\bar{\eta}} \quad \text{, de codimension} \quad m \; ,
\end{equation}
tels que

\begin{equation}\tag{4.4.5}
z_{\bar{\eta}} = P_{\bar{\eta}}(t_{1}(\bar{\eta})) - P_{\bar{\eta}}(t_{2}(\bar{\eta})) \quad \text{sur} \quad X_{\bar{\eta}} \quad .
\end{equation}
Considérons le cycle $P_{\bar{\eta}}$ comme une \underline{correspondance algébrique} sur $(C_{\bar{\eta}}, X_{\bar{\eta}})$ , définissant une correspondance cohomologique, encore notée $P_{\bar{\eta}}$, ou encore un homomorphisme

\begin{equation}\tag{4.4.6}
P_{\bar{\eta}} : H^{*}(C_{\bar{\eta}},\mathbb{Q}_{\ell}(i)) \longrightarrow H^{*+2(m-1)}(X_{\bar{\eta}}, \mathbb{Q}_{\ell}(i+m-1)) \quad .
\end{equation}
Considérons de même la correspondance algébrique $V_{\bar{\eta}}$ (3.3.2) sur $(X_{\bar{\eta}}, X \otimes_{k} k(\bar{\eta}))$ donnée par l'hypothèse (B) de (4.1.3), définissant

\begin{equation}\tag{4.4.7}
V_{\bar{\eta}} : H^{*}(X_{\bar{\eta}}, \mathbb{Q}_{\ell}(i+m-1)) \longrightarrow H^{*}(X\otimes_{k}k(\bar{\eta}), \mathbb{Q}_{\ell}(i+m-1)) \quad ,
\end{equation}
d'où une correspondance algébrique composée $Q_{\bar{\eta}} = V_{\bar{\eta}} \circ P_{\bar{\eta}}$ sur $(C_{\bar{\eta}}, X \otimes_{k} k(\bar{\eta}))$ , définissant

\begin{equation}\tag{4.4.8}
Q_{\bar{\eta}} = V_{\bar{\eta}} \circ P_{\bar{\eta}} : H^{*}(C_{\bar{\eta}},\mathbb{Q}_{\ell}(i)) \longrightarrow H^{*+2(m-1)}(X\otimes_{k}k(\bar{\eta}),\mathbb{Q}_{\ell}(i+m-1))
\end{equation}
Considérons l'inclusion

\begin{equation*}
m : X_{\bar{\eta}} \longrightarrow X \otimes_{k} k(\bar{\eta}) \quad ,
\end{equation*}
donnant la correspondance algébrique $m^{*}$ sur $(X \otimes_{k} k(\bar{\eta}), X_{\bar{\eta}})$, d'où la correspondance composée $m^{*} Q_{\bar{\eta}}$ sur $(C_{\bar{\eta}}, X_{\bar{\eta}})$, définissant 


\SGApage{II}{358}

\begin{equation}\tag{4.4.9}
 m^*Q_{\bar\eta} = m^*V_{\bar\eta} P_{\bar\eta} : H^*(C_{\bar\eta}, \mathbb{Q}_\ell(i)) \longrightarrow H^{*+2(m-1)}(X_{\bar\eta},\mathbb{Q}_\ell(i+m-1)) \quad .
\end{equation}
Considérons la correspondance algébrique

\begin{equation}\tag{4.4.10}
R_{\bar\eta} = P_{\bar\eta} - m^*Q_{\bar\eta} = (\mathrm{id}-m^*V_{\bar\eta})P_{\bar\eta} : H^*(C_{\bar\eta},\mathbb{Q}_\ell(i)) \longrightarrow H^{*+2(m-1)}(X_{\bar\eta},\mathbb{Q}_\ell(i+m-1)).
\end{equation}
Comme $V_{\bar\eta}$ est inverse à gauche de $m^*$ , $(\mathrm{id}-m^*V_{\bar\eta})$ est un projecteur dans $H^*(X_{\bar\eta}, -)$ , dont l'image est un supplémentaire de $\mathrm{Im}\ (m^* : H^*(X \otimes_k k(\bar\eta),-) \longrightarrow H^*(X_{\bar\eta},-))$ . Comme en vertu de l'hypothèse (4.1.2) l'homomorphisme

\begin{equation}\tag{4.4.11}
R_{\bar\eta} : H^1(C_{\bar\eta},\mathbb{Q}_\ell(i)) \longrightarrow H^{2m-1}(X_{\bar\eta},\mathbb{Q}_\ell(i+m-1))
\end{equation}
a son image dans $\mathrm{Im}\ m^*$ , on trouve que

(4.4.12) \quad l'homomorphisme (4.4.11) est nul.

Choisissons maintenant une extension finie

\begin{equation*}
L/k(\eta)
\end{equation*}
au-dessus de laquelle les objets

\begin{equation*}
C_{\bar\eta}, \ t_1(\bar\eta), \ t_2(\bar\eta), \ Q_{\bar\eta} \ , \ R_{\bar\eta}
\end{equation*}
soient déjà définis, et

$U$  un ouvert $\neq \emptyset$  dans le normalisé de $\mathbb{P}^1$  dans  $L$ .

Prenant $U$ assez petit, il existe une courbe relative propre et lisse, à fibres géométriquement connexes 


\SGApage{II}{359}

\begin{equation*}
 C \longrightarrow U \ ,
\end{equation*}
dont la fibre générique géométrique soit $C_{\bar\eta}$ , et deux sections

\begin{equation*}
t_i : U \longrightarrow C \quad i = 1, 2
\end{equation*}
dont les valeurs en $\bar\eta$ sont $t_i(\bar\eta)$ .

Soient

\begin{equation*}
\rho : \widetilde{X} \longrightarrow \mathbb{P}^1
\end{equation*}
la projection (XVIII 3.1.4) dont les fibres sont les sections du pinceau,

\begin{equation*}
\widetilde{X}_U = \widetilde{X} \times_{\mathbb{P}^1} U \ ,
\end{equation*}
et

\begin{equation*}
M : \widetilde{X}_U \hookrightarrow X \times U
\end{equation*}
l'immersion canonique de $\widetilde{X}_U$ dans $X \times U$ (considéré comme la famille constante sur $U$ de valeur $X$ ) ,

\begin{equation*}
z_U = M^* \ \mathrm{pr}_1^*(z) \ ,
\end{equation*}
le cycle algébrique sur $\widetilde{X}_U$ , induit par $z$ . Prenant $U$ assez petit, il existe un cycle algébrique $R$ sur $C \times_U \widetilde{X}_U$ dont la valeur en $C_{\bar\eta} \times X_{\bar\eta}$ est $R_{\bar\eta}$ , et un cycle algébrique $Q$ sur $C \times X \times U$ dont la valeur en $C_{\bar\eta} \times (X \otimes_k k(\bar\eta))$ est $Q_{\bar\eta}$ , tels que l'on ait

\begin{equation}\tag{4.4.13}
z_U = R(t_1) - R(t_2) + (\mathrm{id}\times M)^*[Q(t_1) - Q(t_2)] \quad .
\end{equation}
Pour démontrer le théorème, il suffira, grâce à l'injectivité de
\SGApage{II}{360}
l'homomorphisme de Griffiths  ``modulo partie fixe'' (XVIII 5.8.7)

\begin{equation*}
\mathrm{Prim}^{2m}(X,\mathbb{Q}_\ell(m)) \ \xrightarrow{\ \mathrm{grif}\ }\ \frac{H^1(U,R^{2m-1}\rho_{U*}\mathbb{Q}_\ell(m))}{M^*H^1(U,H^{2m-1}(X,\mathbb{Q}_\ell(m)))} \qquad ,
\end{equation*}
de démontrer que l'image de  $z_U$  par

\begin{equation*}
u_0 \ : \ \mathrm{Prim}^{2m}(\widetilde{X}_{U/U},\mathbb{Q}_\ell(m)) \longrightarrow H^1(U,R^{2m-1}\rho_{U*}\mathbb{Q}_\ell(m))
\end{equation*}
se trouve dans $M^*\bigl(H^1(U,H^{2m-1}(X,\mathbb{Q}_\ell(m)))\bigr)$.

Or, compte tenu de la décomposition (4.4.13), et de la commutativité de (1.4.2),

\begin{center}
\begin{tikzcd}[column sep=huge, row sep=huge]
\mathrm{Prim}^{2}(C/U,\mathbb{Q}_\ell(1)) \arrow[r, "Q"] & \mathrm{Prim}^{2m}(X\times U/U,\mathbb{Q}_\ell(m)) \arrow[r, "M^*"] \arrow[d, "u_{pr_2}"] & \mathrm{Prim}^{2m}(\widetilde{X}_{U/U},\mathbb{Q}_\ell(m)) \arrow[d, "u_0"] \\
 {} & H^1(U,H^{2m-1}(X,\mathbb{Q}_\ell(m))) \arrow[r, "M^*"] & H^1(U,R^{2m-1}\rho_{U*}\mathbb{Q}_\ell(m))\ ,
\end{tikzcd}
\end{center}












il suffit de démontrer

\begin{equation*}
u_0(R(t_1) - R(t_2)) = 0 \quad \text{dans} \quad H^1(U,R^{2m-1}\rho_{U*}\mathbb{Q}_\ell(m)) \quad ,
\end{equation*}
qui est conséquence de (4.4.12), grâce à 1.7.


5.  \underline{Le groupe de Griffiths}

5.0.  Soit  $S$  propre et lisse sur un corps  $k$  algébriquement clos. Désignons par
\SGApage{II}{361}
(5.0.1)   $Z^i(S)$  le groupe des cycles algébriques de codimension $i$  sur $S$

(5.0.2)   $Z^i_{\mathrm{alg}}(S)$ le sous-groupe de  $Z^i(S)$  formé des cycles algébriquement équivalents à zéro,

et, pour tout nombre premier  $\ell \neq \operatorname{car}(k)$,

(5.0.3)   $Z^i_{\ell-\mathrm{coh}}(S)$  le sous-groupe de  $Z^i(S)$  formé des cycles dont la classe de cohomologie dans  $H^{2i}(S,\mathbb{Q}_\ell(i))$  est nulle.

(On conjecture [4] que ce groupe est indépendant de $\ell$, ce qui est vrai du moins si $\operatorname{car}(k)=0$.)

On pose

\begin{equation}\tag{5.0.4}
\mathrm{Grif}^i_\ell(S) = Z^i_{\ell-\mathrm{coh}}(S)/\ Z^i_{\mathrm{alg}}(S) \quad .
\end{equation}
Si de plus $S$ est projectif et muni d'une immersion projective, on pose

(5.0.5)   $Z^{i,\mathrm{prim}}(S) =$ le sous-groupe de  $Z^i(S)$  formé des cycles qui sont primitifs (i.e. dont la classe de cohomologie l'est),

(5.0.6)   $\mathrm{Prim}^{2i}_{\mathrm{alg}}(S,\mathbb{Q}_\ell(i)) =$ le sous-$\mathbb{Q}$-vectoriel de  $H^{2i}(S,\mathbb{Q}_\ell(i))$ engendré par des classes de cohomologie des cycles algébriques primitifs.

\underline{Corollaire} 5.1    \underline{Sous les hypothèses de}  4.1, \underline{on a}

\begin{equation}\tag{5.1.1}
\dim_{\mathbb{Q}}(\mathrm{Grif}^m_\ell(X_{\overline{\eta}})\otimes_{\mathbb{Z}}\mathbb{Q}) \ \geq \ \dim_{\mathbb Q}(\mathrm{Prim}^{2m}_{\mathrm{alg}}(X,\mathbb{Q}_\ell(m)))
\end{equation}
En effet, d'après (4.1.5), le noyau de la flèche composée

\begin{equation*}
\mathbb{Q}\otimes_{\mathbb{Z}}Z^{m,\mathrm{prim}}(X) \ \xrightarrow{\ \text{rest. à } X_{\overline{\eta}}\ }\ \mathbb{Q} \otimes_{\mathbb{Z}}Z^m_{\ell-\mathrm{coh}}(X_{\overline{\eta}}) \longrightarrow \mathrm{Grif}^m_\ell(X_{\overline{\eta}}) \quad 
\end{equation*}

\SGApage{II}{362}

 est \underline{contenu} dans $Z^m_{\ell-\mathrm{coh}}(X) \otimes_{\mathbb{Z}} \mathbb{Q}$, de sorte que $\mathrm{Prim}^{2m}_{\mathrm{alg}}(X,\mathbb{Q}_{\ell}(m))$ est un quotient d'un sous-groupe de $\mathrm{Grif}^m_\ell(X_{\overline{\eta}}) \otimes_{\mathbb{Z}} \mathbb{Q}$, ce qui achève la démonstration.

\underline{Remarque} 5.2.  Pour $X$ une hypersurface quadrique dans $\mathbb{P}^{2m+1}$ on a

\begin{equation*}
\dim_{\mathbb{Q}_{\ell}}(\mathrm{Prim}^{2m}_{\mathrm{alg}}(X,\mathbb{Q}_{\ell}(m))) = 1
\end{equation*}
\underline{En particulier} ($m=2$), \underline{pour} $X$ \underline{une quadrique dans} $\mathbb{P}^5$, \underline{la section de} $X$ \underline{par une hypersurface générique de degré} $> 5$ \underline{contient une courbe,} $\mathbb{Q}_{\ell}$\underline{-cohomologue à zéro}, \underline{dont aucun multiple non nul n'est algébriquement équivalent à zéro.}


